/* =============================================================================
   HELPERS
============================================================================ */

const fmtCurrency = (n) =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(Math.round(n || 0));

const fmtCurrencyShort = (n) => {
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(2).replace(/\.0+$/, "")}M`;
  if (n >= 1_000) return `$${Math.round(n / 1_000)}K`;
  return fmtCurrency(n);
};

/* State adjustment to savings: high-cost states see higher savings because the
   insourced overhead they're carrying is heavier. We use (SUI_avg + WC_rate)
   as a state overhead score; national average is ~4.8. */
function stateSavingsMultiplier(stateName) {
  if (!stateName) return 1.0;
  const row = STATES.find((s) => s.name === stateName);
  if (!row) return 1.0;
  const score = row.suiAvg + row.wcRate;
  const avgScore = 4.8;
  const deviation = score - avgScore;
  const multiplier = 1.0 + deviation * 0.03;
  return Math.max(0.92, Math.min(1.12, multiplier));
}

function computeSavings({ annualSpend, shifts, state }) {
  if (!annualSpend || annualSpend <= 0) return null;
  const stateMult = stateSavingsMultiplier(state);
  const midpoint = annualSpend * BASE_SAVINGS_PCT * stateMult;
  const low  = shifts === "3" ? midpoint * SHIFT_3_LOW  : midpoint * RANGE_LOW;
  const high = shifts === "3" ? midpoint * SHIFT_3_HIGH : midpoint * RANGE_HIGH;
  return { low, high, midpoint, stateMult };
}

function isWorkEmail(email) {
  if (!email || !email.includes("@")) return false;
  const domain = email.split("@")[1].toLowerCase().trim();
  return !BLOCKED_EMAIL_DOMAINS.includes(domain);
}

/* Build the Calendly URL with prefill so the booking arrives with full context.
   Calendly forwards utm_* and a1/a2 params to its ActiveCampaign integration.
   The a1 prefill explicitly tells Jay which specialist to add to the meeting
   invite based on the prospect's vertical, or signals that he handles the
   call himself (grocery). */
function buildCalendlyUrl({ vertical, state, size, shifts, annualSpend, savings }) {
  const base = CALENDLY_LINKS[vertical];
  if (!base) return null;
  const sizeLabel = FACILITY_SIZES.find((s) => s.id === size)?.label || size;
  const verticalLabel = VERTICAL_OPTIONS.find((v) => v.id === vertical)?.label;
  const specialist = SPECIALIST_BY_VERTICAL[vertical];
  const inviteLead = specialist
    ? `ADD TO INVITE: ${specialist}`
    : `RUN SOLO: grocery is your vertical, no add needed`;
  const params = new URLSearchParams({
    utm_source: "tec_lite_calculator",
    utm_medium: "embedded_widget",
    utm_campaign: "savings_estimate",
    utm_content: `${vertical}_${state}_${shifts}shift`,
    a1: `${inviteLead} | State: ${state} | Vertical: ${verticalLabel} | Size: ${sizeLabel} | Shifts: ${shifts} | Annual spend: $${annualSpend.toLocaleString()} | Projected savings: $${Math.round(savings.low).toLocaleString()} to $${Math.round(savings.high).toLocaleString()}`,
  });
  return `${base}?${params.toString()}`;
}

