/* =============================================================================
   CALENDLY EMBED — loads the Calendly widget script + CSS once on mount
============================================================================ */
function CalendlyInlineEmbed({ url }) {
  const [loaded, setLoaded] = useState(false);
  const [showFallback, setShowFallback] = useState(false);
  const widgetRef = useRef(null);

  useEffect(() => {
    if (!url) return;
    let cancelled = false;

    const ensureCss = () => {
      if (!document.querySelector('link[data-calendly-css]')) {
        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = "https://assets.calendly.com/assets/external/widget.css";
        link.setAttribute("data-calendly-css", "true");
        document.head.appendChild(link);
      }
    };

    const initWidget = () => {
      if (cancelled || !widgetRef.current) return;
      // If Calendly's global object loaded, manually initialize the widget
      if (window.Calendly && typeof window.Calendly.initInlineWidget === "function") {
        window.Calendly.initInlineWidget({
          url,
          parentElement: widgetRef.current,
        });
        setLoaded(true);
      }
    };

    const ensureScript = () => {
      const existing = document.querySelector('script[data-calendly-widget]');
      if (existing) {
        // Script already there; if Calendly is loaded, init immediately
        if (window.Calendly) {
          initWidget();
        } else {
          existing.addEventListener("load", initWidget, { once: true });
        }
        return;
      }
      const script = document.createElement("script");
      script.src = "https://assets.calendly.com/assets/external/widget.js";
      script.async = true;
      script.setAttribute("data-calendly-widget", "true");
      script.addEventListener("load", initWidget, { once: true });
      script.addEventListener("error", () => {
        if (!cancelled) setShowFallback(true);
      });
      document.body.appendChild(script);
    };

    ensureCss();
    ensureScript();

    // If the widget hasn't rendered iframe content in 4 seconds, reveal the fallback
    const timer = setTimeout(() => {
      if (cancelled) return;
      const iframe = widgetRef.current?.querySelector("iframe");
      if (!iframe) setShowFallback(true);
    }, 4000);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [url]);

  if (!url) {
    return (
      <div style={{ padding: 24, textAlign: "center", color: "var(--tec-text-secondary)" }}>
        Calendar unavailable. Please reach us at hello@tecserv.com.
      </div>
    );
  }

  return (
    <div style={{ position: "relative" }}>
      <div
        ref={widgetRef}
        className="calendly-inline-widget"
        data-url={url}
        style={{ minWidth: 320, height: 700 }}
      />
      {!loaded && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: "white",
            borderRadius: 12,
            pointerEvents: showFallback ? "auto" : "none",
          }}
        >
          {!showFallback ? (
            <div style={{ color: "var(--tec-text-secondary)", fontSize: 15 }}>
              Loading calendar...
            </div>
          ) : (
            <div style={{ textAlign: "center", padding: 24, maxWidth: 480 }}>
              <p
                style={{
                  fontSize: 16,
                  color: "var(--tec-text)",
                  marginBottom: 20,
                  lineHeight: 1.5,
                }}
              >
                The booking calendar didn't load in this preview. Click below
                to open it in a new tab.
              </p>
              <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  display: "inline-block",
                  backgroundColor: "var(--tec-blue)",
                  color: "white",
                  fontFamily: "'Open Sans', sans-serif",
                  fontWeight: 700,
                  fontSize: 16,
                  padding: "14px 28px",
                  borderRadius: 8,
                  textDecoration: "none",
                }}
              >
                Open booking calendar →
              </a>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* =============================================================================
   MAIN COMPONENT — 3 FRAMES
============================================================================ */

export default function TecLiteQuiz() {
  // Step: 1 = quiz, 2 = results preview, 3 = Calendly + follow-up later
  const [step, setStep] = useState(1);

  // Quiz inputs
  const [stateName, setStateName] = useState("");
  const [vertical, setVertical] = useState("");
  const [size, setSize] = useState("");
  const [shifts, setShifts] = useState("");
  const [annualSpend, setAnnualSpend] = useState(0);

  // Scroll to top on step change
  const containerRef = useRef(null);
  useEffect(() => {
    containerRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [step]);

  // Derived
  const quizComplete = stateName && vertical && size && shifts && annualSpend > 0;
  const savings = quizComplete
    ? computeSavings({ annualSpend, shifts, state: stateName })
    : null;
  const verticalLabel = vertical
    ? VERTICAL_OPTIONS.find((v) => v.id === vertical)?.label
    : "";
  const sizeLabel = size
    ? FACILITY_SIZES.find((s) => s.id === size)?.label.toLowerCase()
    : "";

  const calendlyUrl =
    step === 3 && savings
      ? buildCalendlyUrl({
          vertical,
          state: stateName,
          size,
          shifts,
          annualSpend,
          savings,
        })
      : null;

  /* ---------------------------------------------------------------------------
     RENDER
  --------------------------------------------------------------------------- */
  return (
    <div
      ref={containerRef}
      style={{
        minHeight: "100vh",
        backgroundColor: "var(--tec-bg)",
        fontFamily: "'Open Sans', sans-serif",
        color: "var(--tec-text)",
      }}
    >
      <style>{BRAND_CSS}</style>

      {/* HEADER */}
      <header
        style={{
          padding: "24px 0",
          borderBottom: "1px solid var(--tec-border)",
          backgroundColor: "white",
        }}
      >
        <div className="max-w-6xl mx-auto px-6">
          <img
            src={TEC_LOGO_BASE64}
            alt="TEC Services"
            style={{ height: 56, width: "auto" }}
          />
        </div>
      </header>

      {/* ============================================================
          FRAME 1: QUIZ
      ============================================================ */}
      {step === 1 && (
        <section style={{ padding: "64px 0 80px" }}>
          <div className="max-w-3xl mx-auto px-6">
            <ProgressDots step={1} total={3} />
            <div className="text-center mb-10">
              <Eyebrow>Free Cost Analysis · 2 minutes</Eyebrow>
              <H1>How much could you save by outsourcing sanitation?</H1>
              <p
                className="text-[18px] leading-[1.55]"
                style={{ color: "var(--tec-text-secondary)" }}
              >
                Most facilities understate their true insourced sanitation
                cost by 20–40 percent because the real spend is buried across
                HR, finance, and operations. Answer five quick questions to
                see a directional estimate.
              </p>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: 16,
                padding: "32px",
                boxShadow: "0 4px 16px rgba(0,0,0,0.04)",
                border: "1px solid var(--tec-border)",
              }}
            >
              <div className="mb-6">
                <Label required>State</Label>
                <Select
                  value={stateName}
                  onChange={setStateName}
                  options={STATES.map((s) => ({ id: s.name, label: s.name }))}
                  placeholder="Select your state..."
                />
                <p
                  className="text-[13px] -mt-2"
                  style={{ color: "var(--tec-text-secondary)" }}
                >
                  Drives state-specific SUI and worker's comp assumptions.
                </p>
              </div>

              <div className="mb-6">
                <Label required>Vertical</Label>
                <Select
                  value={vertical}
                  onChange={setVertical}
                  options={VERTICAL_OPTIONS}
                  placeholder="Select your vertical..."
                />
              </div>

              <div className="mb-6">
                <Label required>Facility size</Label>
                <Select
                  value={size}
                  onChange={setSize}
                  options={FACILITY_SIZES}
                  placeholder="Select facility size..."
                />
              </div>

              <div className="mb-6">
                <Label required>Shifts per day</Label>
                <Select
                  value={shifts}
                  onChange={setShifts}
                  options={SHIFT_OPTIONS}
                  placeholder="Select shift count..."
                />
              </div>

              <div className="mb-2">
                <Label required>Current annual sanitation spend</Label>
                <CurrencyInput
                  value={annualSpend}
                  onChange={setAnnualSpend}
                  placeholder="e.g., 850000"
                />
                <p
                  className="text-[13px] -mt-2"
                  style={{ color: "var(--tec-text-secondary)" }}
                >
                  Estimate is fine. Include wages, taxes, benefits, recruiting,
                  and supervision overhead.
                </p>
              </div>

              <div className="mt-8">
                <PrimaryButton
                  onClick={() => setStep(2)}
                  disabled={!quizComplete}
                  fullWidth
                >
                  See my savings estimate →
                </PrimaryButton>
              </div>
            </div>
          </div>
        </section>
      )}

      {/* ============================================================
          FRAME 2: RESULTS PREVIEW
      ============================================================ */}
      {step === 2 && savings && (
        <section style={{ padding: "64px 0 80px" }}>
          <div className="max-w-2xl mx-auto px-6">
            <ProgressDots step={2} total={3} />
            <div className="text-center mb-8">
              <Eyebrow>Your projected savings</Eyebrow>
              <p
                className="text-[16px] mb-4"
                style={{ color: "var(--tec-text-secondary)" }}
              >
                Based on a{" "}
                <strong style={{ color: "var(--tec-purple)" }}>
                  {shifts}-shift {sizeLabel} {verticalLabel.toLowerCase()} facility
                </strong>{" "}
                in{" "}
                <strong style={{ color: "var(--tec-purple)" }}>
                  {stateName}
                </strong>{" "}
                spending{" "}
                <strong style={{ color: "var(--tec-purple)" }}>
                  {fmtCurrency(annualSpend)}
                </strong>{" "}
                annually on insourced sanitation:
              </p>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: 16,
                padding: "48px 32px",
                boxShadow: "0 4px 16px rgba(0,0,0,0.04)",
                border: "1px solid var(--tec-border)",
                textAlign: "center",
              }}
            >
              <div
                style={{
                  fontSize: 72,
                  fontWeight: 700,
                  color: "var(--tec-blue)",
                  lineHeight: 1.05,
                  marginBottom: 8,
                }}
              >
                {fmtCurrencyShort(savings.low)} – {fmtCurrencyShort(savings.high)}
              </div>
              <p
                className="text-[16px] mb-6"
                style={{ color: "var(--tec-text-secondary)" }}
              >
                Projected annual savings with TEC Services
              </p>

              <div
                style={{
                  borderTop: "1px solid var(--tec-border)",
                  paddingTop: 24,
                  marginTop: 8,
                  textAlign: "left",
                }}
              >
                <p
                  className="text-[15px] leading-[1.6] mb-3"
                  style={{ color: "var(--tec-text)" }}
                >
                  <strong>This is a directional estimate.</strong>
                </p>
                <p
                  className="text-[14px] leading-[1.6]"
                  style={{ color: "var(--tec-text-secondary)" }}
                >
                  The full line-item breakdown happens live with the TEC Services
                  team, including the right specialist for your {verticalLabel.toLowerCase()}{" "}
                  operation. In 15 minutes you'll walk through wages, taxes, benefits,
                  recruiting, supervision, and efficiency math against {stateName}'s
                  actual 2026 rates. You'll leave the call with a personalized PDF
                  tailored to your facility.
                </p>
              </div>
            </div>

            <div className="mt-8 flex flex-col items-center gap-3">
              <PrimaryButton onClick={() => setStep(3)} fullWidth>
                Book 15 minutes with our team →
              </PrimaryButton>
              <GhostButton onClick={() => setStep(1)}>
                ← Edit my inputs
              </GhostButton>
            </div>
          </div>
        </section>
      )}

      {/* ============================================================
          FRAME 3: CALENDLY EMBED + FOLLOW-UP LATER
      ============================================================ */}
      {step === 3 && savings && (
        <section style={{ padding: "48px 0 80px" }}>
          <div className="max-w-3xl mx-auto px-6">
            <ProgressDots step={3} total={3} />

            {/* Small savings reminder pinned to top */}
            <div
              style={{
                backgroundColor: "white",
                borderRadius: 12,
                padding: "16px 24px",
                marginBottom: 32,
                border: "1px solid var(--tec-border)",
                display: "flex",
                flexWrap: "wrap",
                gap: 8,
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div
                className="text-[13px]"
                style={{ color: "var(--tec-text-secondary)" }}
              >
                Projected savings ·{" "}
                <strong style={{ color: "var(--tec-purple)" }}>
                  {verticalLabel}
                </strong>{" "}
                in{" "}
                <strong style={{ color: "var(--tec-purple)" }}>
                  {stateName}
                </strong>
              </div>
              <div
                style={{
                  fontSize: 18,
                  fontWeight: 700,
                  color: "var(--tec-blue)",
                }}
              >
                {fmtCurrencyShort(savings.low)} – {fmtCurrencyShort(savings.high)}
              </div>
            </div>

            <div className="text-center mb-8">
              <Eyebrow>Last step</Eyebrow>
              <h2
                style={{
                  fontSize: 32,
                  fontWeight: 700,
                  color: "var(--tec-text)",
                  marginBottom: 12,
                  lineHeight: 1.2,
                }}
              >
                Book 15 minutes with our team
              </h2>
              <p
                style={{
                  fontSize: 16,
                  color: "var(--tec-text-secondary)",
                  maxWidth: 560,
                  margin: "0 auto",
                  lineHeight: 1.55,
                }}
              >
                You'll meet the TEC Services team, including the right specialist for your {verticalLabel.toLowerCase()} operation. Walk through the full line-item analysis and leave with a personalized PDF.
              </p>
            </div>

            {/* Calendly inline */}
            <div
              style={{
                backgroundColor: "white",
                borderRadius: 16,
                padding: 16,
                border: "1px solid var(--tec-border)",
                boxShadow: "0 4px 16px rgba(0,0,0,0.04)",
              }}
            >
              <CalendlyInlineEmbed url={calendlyUrl} />
            </div>


            <div className="text-center mt-8">
              <GhostButton onClick={() => setStep(2)}>
                ← Back to results
              </GhostButton>
            </div>
          </div>
        </section>
      )}

    </div>
  );
}
